INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch05$PT143-S3-Q2$batch05$, 143, 3, 2, $batch05$Necessary Assumption$batch05$, $batch05$While sales of other highly fuel-efficient automobiles are in decline, sales of the Hydro are rising. The Hydro’s manufacturers attribute its success to the Hydro’s price and very low fuel consumption. However, the Hydro is comparable in price and fuel efficiency to its competitors, so it is more likely that its success is due to the fact that people want to appear environmentally conscious to their neighbors.$batch05$, $batch05$Which one of the following is an assumption required by the argument?$batch05$, $batch05$B$batch05$, true, $batch05$Batch 05; question text from local bank.$batch05$ FROM lr_sections s WHERE s.preptest=143 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT143-S3-Q2$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$A$batch05$, $batch05$The Hydro is the most popular highly fuel-efficient automobile available.$batch05$, $batch05$Not Necessary$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT143-S3-Q2$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$A$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$B$batch05$, $batch05$The Hydro is recognizable as environmentally friendly in a way that its competitors are not.$batch05$, $batch05$Correct$batch05$, true FROM lr_questions q WHERE q.qid=$batch05$PT143-S3-Q2$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$B$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$C$batch05$, $batch05$The Hydro has a better safety record than its competitors.$batch05$, $batch05$Weakens$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT143-S3-Q2$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$C$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$D$batch05$, $batch05$Hydro buyers are more likely to have neighbors who also drive Hydros.$batch05$, $batch05$Out of Scope$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT143-S3-Q2$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$D$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$E$batch05$, $batch05$Hydro buyers have less interest in environmental causes than buyers of other highly fuel-efficient automobiles.$batch05$, $batch05$Out of Scope$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT143-S3-Q2$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$E$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT143-S3-Q2$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$The Hydro's success is more likely due to people wanting to appear environmentally conscious to their neighbors.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$The Hydro's sales are rising while other fuel-efficient cars decline. It matches its competitors on price and fuel efficiency.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$This is a comparison. The author's explanation has to account for the *difference* between the Hydro and its competitors. But every fuel-efficient car signals environmental concern. If the neighbors cannot tell a Hydro apart from the rest, wanting to look green would help all of them equally. For the explanation to work, the Hydro has to stand out.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A defender: the Hydro is seen as green in a way its competitors are not.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT143-S3-Q2$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$The Hydro does not need to be the best-seller, only to be gaining while others lose.$batch05$), ($batch05$B$batch05$, $batch05$Negate it: "the Hydro is *not* recognizable as environmentally friendly in any way its competitors are not." Then the urge to look green helps every competitor just as much, and it cannot explain why only the Hydro is rising.$batch05$), ($batch05$C$batch05$, $batch05$A better safety record is a different explanation for the Hydro's success, which works against the author.$batch05$), ($batch05$D$batch05$, $batch05$Whether neighbors drive Hydros is beside the point. The question is whether the car signals anything to them.$batch05$), ($batch05$E$batch05$, $batch05$The argument is about *appearing* environmentally conscious. How much buyers actually care about the environment does not matter.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT143-S3-Q2$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
